body.script:
		const translations = {
			ca: {
				canviIdiomaText: "Idioma",
				pageTitle: "En manteniment",
        explicacio: "Degut a tasques de manteniment, l'accés a l'aplicació no està disponible.  Per a més informació podeu contactar amb el CAS.",
				contacteText: "Centre d'Atenció i Suport (CAS)",
        correuText: "Correu electrònic: cas@uab.cat",
        telefonText: "Telèfon: 935812100",
        dreceresText: "Més informació",
				drecera1Text: "Incidències i intervencions",
				experienciesText: "La UAB és una universitat jove, pública i capdavantera. Líder als rànquings internacionals i referent en recerca. Barcelonina, catalana i internacional. Una universitat transformadora, solidària, diversa i igualitària, sostenible i saludable, participativa i cultural. I una universitat de campus, amb les facultats i les escoles, els instituts de recerca i els serveis en un entorn natural on viure experiències úniques.",
				ariaUabLogoText: "Universitat Autònoma de Barcelona",
				ariaLegalText: "Informació tècnica i legal",
				legal1Text: "Avís legal",
				legal2Text: "Protecció de dades",
				legal3Text: "Accessibilitat web",
				legal4Text: "Mapa del web UAB"
			},
			es: {
				canviIdiomaText: "Idioma",
				pageTitle: "En mantenimiento",
				explicacio: "Debido a tareas de mantenimiento, el acceso a la aplicación no está disponible.  Para más información, podéis contactar con el CAS.",
				contacteText: "Centre d'Atenció i Suport (CAS)",
        correuText: "Correo electrónico: cas@uab.cat",
        telefonText: "Teléfono: 935812100",
        dreceresText: "Más información",
				drecera1Text: "Incidencias e intervenciones",
				experienciesText: "La UAB es una universidad joven, pública y puntera. Líder en los rankings internacionales y referente en investigación. Barcelonesa, catalana e internacional. Una universidad transformadora, solidaria, diversa e igualitaria, sostenible y saludable, participativa y cultural. Y una universidad de campus, con las facultades y las escuelas, los institutos de investigación y los servicios en un entorno natural donde vivir experiencias únicas.",
				ariaUabLogoText: "Universitat Autònoma de Barcelona",
				ariaLegalText: "Información técnica y legal",
				legal1Text: "Aviso legal",
				legal2Text: "Protección de datos",
				legal3Text: "Accesibilidad web",
				legal4Text: "Mapa del web UAB"
			},
			en: {
				canviIdiomaText: "Language",
				pageTitle: "Under maintenance",
        explicacio: "Due to maintenance tasks, access to the application is not available.   For more information, you can contact the CAS.",
				contacteText: "Centre d'Atenció i Suport (CAS)",
        correuText: "Email: cas@uab.cat",
        telefonText: "Phone: 935812100",
        dreceresText: "More information",
				drecera1Text: "Technical issues and interventions",
				experienciesText: "The UAB is a young, public and groundbreaking university. A leader in international rankings and a benchmark in research. Barcelonian, Catalan and international. A transformative, supportive, diverse and egalitarian, sustainable and healthy, participative and cultural university. And a campus university, with its faculties and schools, research institutes and services all within a natural environment that offers a variety of unique experiences.",
				ariaLegalText: "Technical and legal information",
				legal1Text: "Legal notice",
				legal2Text: "Data protection",
				legal3Text: "Web accessibility",
				legal4Text: "UAB Site map"
			}
		};
		function getBrowserLanguage() {
			const browserLang = navigator
				.language
				.slice(0, 2);
			return ['ca', 'es', 'en'].includes(browserLang) ?
				browserLang :
				'ca';
		}
		function changeLanguage(lang) {
			if (!translations.hasOwnProperty(lang)) {
				console.warn(`Invalid language: ${lang}`);
				lang = 'ca';
			}
			const translationsForLang = translations[lang];
			const elements = document.querySelectorAll('[data-translate]');
			document.documentElement.lang = lang;
			try {
				const radio = document.querySelector(`input[name="lang"][value="${lang}"]`);
				if (radio)
					radio.checked = true;
			} catch (e) {
				console.warn('Language radio button not found');
			}
			document
				.querySelectorAll('[data-translate-aria]')
				.forEach(el => {
					const key = el.getAttribute('data-translate-aria');
					if (translationsForLang.hasOwnProperty(key)) {
						el.setAttribute('aria-label', translationsForLang[key]);
					}
				});
			elements.forEach(el => {
				const key = el.getAttribute('data-translate');
				if (translationsForLang.hasOwnProperty(key)) {
					el.innerHTML = translationsForLang[key];
				} else {
					console.warn(`Missing translation for key: ${key}`);
				}
			});
		}
		document.addEventListener('DOMContentLoaded', () => {
			changeLanguage(getBrowserLanguage());
			document
				.querySelectorAll('input[name="lang"]')
				.forEach(radio => radio.addEventListener('change', e => changeLanguage(e.target.value)));
		});
